const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const keukenhof = ee.Geometry.Point([4.5422, 52.2709]).buffer(1000); // Buffer of 1km around Keukenhof

  const date1 = '2018-04-21';
  const date2 = '2018-05-07';

  // Function to mask clouds in Sentinel-2 QA60 band
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to 0-1 range
  }

  // Function to get and process Sentinel-2 image for a given date and geometry
  async function getImageStats(targetDate, geom, dateRangeDays = 3) {
    const startDate = ee.Date(targetDate).advance(-dateRangeDays, 'day');
    const endDate = ee.Date(targetDate).advance(dateRangeDays, 'day');

    let collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geom)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter for less cloudy images
      .map(maskS2clouds)
      .select('B4'); // Select the Red band

    // Prioritize image closest to the target date
    const colSize = await collection.size().getInfo();
    if (colSize === 0) {
      // Try L1C if L2A has no results, but without atmospheric correction,
      // direct comparison might be less accurate. Given the nature of the question
      // and the specific dates, L2A is preferred. Let's just widen the date range instead.
      // (This specific problem's constraint will not allow widening, so will just return nothing.)
      return { image: null, meanRed: null, pixelCount: 0, cloudCover: null, actualDate: null };
    }

    // Sort by absolute difference from targetDate
    collection = collection.map(image => {
      const imageDate = image.date();
      const diff = ee.Number(imageDate.difference(ee.Date(targetDate), 'day')).abs();
      return image.set('date_diff', diff);
    });
    const bestImage = collection.sort('date_diff').first();

    if (!bestImage) {
      return { image: null, meanRed: null, pixelCount: 0, cloudCover: null, actualDate: null };
    }

    const meanRed = await bestImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 10, // Sentinel-2 resolution
      maxPixels: 1e9
    }).get('B4').getInfo();

    const pixelCount = await bestImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 10,
      maxPixels: 1e9
    }).get('B4').getInfo();

    const cloudCover = await bestImage.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();
    const actualDate = await ee.Date(bestImage.get('system:time_start')).format('YYYY-MM-dd').getInfo();

    return { image: bestImage, meanRed: meanRed, pixelCount: pixelCount, cloudCover: cloudCover, actualDate: actualDate };
  }

  console.log(`Analyzing Keukenhof Garden (Point: [4.5422, 52.2709], Buffer: 1km)`);

  // Process for April 21, 2018
  const stats1 = await getImageStats(date1, keukenhof);
  // Process for May 7, 2018
  const stats2 = await getImageStats(date2, keukenhof);

  // 2. Data Acquisition & Check
  if (!stats1.image || stats1.pixelCount === 0) {
    console.log(`No valid image found for around ${date1} or no valid pixels remain.`);
    if (!stats1.image) { console.log("April: C1"); } else { console.log("April: C2"); }
  } else {
    console.log(`April 21, 2018 (Actual: ${stats1.actualDate}): Mean Red B4 = ${stats1.meanRed !== null ? stats1.meanRed.toFixed(4) : 'N/A'}, Valid Pixels = ${stats1.pixelCount}, Cloud Cover = ${stats1.cloudCover !== null ? stats1.cloudCover.toFixed(2) + '%' : 'N/A'}`);
  }

  if (!stats2.image || stats2.pixelCount === 0) {
    console.log(`No valid image found for around ${date2} or no valid pixels remain.`);
    if (!stats2.image) { console.log("May: C1"); } else { console.log("May: C2"); }
  } else {
    console.log(`May 7, 2018 (Actual: ${stats2.actualDate}): Mean Red B4 = ${stats2.meanRed !== null ? stats2.meanRed.toFixed(4) : 'N/A'}, Valid Pixels = ${stats2.pixelCount}, Cloud Cover = ${stats2.cloudCover !== null ? stats2.cloudCover.toFixed(2) + '%' : 'N/A'}`);
  }

  // Handle C1/C2 conditions
  if (!stats1.image || stats1.pixelCount === 0 || !stats2.image || stats2.pixelCount === 0) {
    // If either date has no image or no valid pixels, determine the specific C1/C2
    if ((!stats1.image && !stats2.image) || (!stats1.image && stats2.pixelCount === 0) || (stats1.pixelCount === 0 && !stats2.image)) {
        console.log("C1"); // Both missing images or one missing image and other has no pixels
    } else if (!stats1.image || !stats2.image) {
        console.log("C1"); // One of the collections is empty
    } else if (stats1.pixelCount === 0 || stats2.pixelCount === 0) {
        console.log("C2"); // One of the collections has valid images, but 0 pixels after masking/clipping
    }
    return; // Exit as we can't compare
  }


  // 4. Calculation & Validation
  const meanRed1 = stats1.meanRed;
  const meanRed2 = stats2.meanRed;

  if (meanRed1 === null || meanRed2 === null || isNaN(meanRed1) || isNaN(meanRed2)) {
    console.log("C3"); // Calculation failed, resulting in null or NaN
    return;
  }

  // Comparison: Higher Red B4 value means more red visible
  if (meanRed1 > meanRed2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
